-- Primebrick: trigger-it-attivatore — translates the English noun
-- "trigger" into Italian "attivatore/attivatori" on every user-facing
-- it-IT surface (nav, sections, entity names, form copy, hints,
-- status labels, action confirmations). Grammatical agreement follows
-- the masculine noun: "la trigger" → "l'attivatore", "questa trigger"
-- → "questo attivatore", "delle trigger" → "degli attivatori",
-- "Spegnila" → "Spegnilo", "i trigger" → "gli attivatori".
-- Code literals are preserved (`triggers` as the NATS resource name,
-- `jobs.ctl.triggers.changed`); only it-IT values change.

UPDATE job.translations SET value = 'Attivatore',             updated_at = now(), updated_by = 'migration-trigger-it', version = version + 1 WHERE key = 'job.entities.job_schedule.fields.trigger_uuid'           AND language = 'it-IT' AND deleted_at IS NULL;
UPDATE job.translations SET value = 'Attivatore',             updated_at = now(), updated_by = 'migration-trigger-it', version = version + 1 WHERE key = 'job.entities.job_schedule.status.trigger'                 AND language = 'it-IT' AND deleted_at IS NULL;
