UPDATE job.translations SET value = 'Chi o cosa ha armato questa pianificazione — l''attivatore proprietario o il modulo che l''ha dichiarata. Apri la cella per ispezionare il record.', updated_at = now(), updated_by = 'migration-trigger-it', version = version + 1 WHERE key = 'job.entities.job_schedule.hints.armed_by' AND language = 'it-IT' AND deleted_at IS NULL;
UPDATE job.translations SET value = 'Quando il job è stato eseguito l''ultima volta — conta ogni origine (attivatore, modulo, sistema, utente). Le esecuzioni soppresse sono escluse: un due saltato non è mai stato eseguito.', updated_at = now(), updated_by = 'migration-trigger-it', version = version + 1 WHERE key = 'job.entities.job_schedule.hints.fired_at' AND language = 'it-IT' AND deleted_at IS NULL;
UPDATE job.translations SET value = 'Se attiva, l''attivatore reagisce all''evento scelto. Spegnilo per metterlo in pausa senza eliminarlo.', updated_at = now(), updated_by = 'migration-trigger-it', version = version + 1 WHERE key = 'job.entities.job_trigger.hints.enabled' AND language = 'it-IT' AND deleted_at IS NULL;
UPDATE job.translations SET value = 'L''evento che può attivare questo attivatore: quando succede qualcosa nel sistema (per esempio un cliente supera una soglia) l''attivatore può partire. Scegli un evento disponibile dall''elenco.', updated_at = now(), updated_by = 'migration-trigger-it', version = version + 1 WHERE key = 'job.entities.job_trigger.hints.event_subject' AND language = 'it-IT' AND deleted_at IS NULL;
UPDATE job.translations SET value = 'Condizioni JSON che devono corrispondere tutte al payload dell''evento perché l''attivatore scatti — un array di voci `{ field, op, value }` valutate sull''evento.', updated_at = now(), updated_by = 'migration-trigger-it', version = version + 1 WHERE key = 'job.entities.job_trigger.hints.filter' AND language = 'it-IT' AND deleted_at IS NULL;
UPDATE job.translations SET value = 'Quando questo attivatore ha prodotto l''ultima esecuzione.', updated_at = now(), updated_by = 'migration-trigger-it', version = version + 1 WHERE key = 'job.entities.job_trigger.hints.last_run' AND language = 'it-IT' AND deleted_at IS NULL;
UPDATE job.translations SET value = 'Prossimo avvio pianificato dell''attivatore armato. Vuoto se disarmato, solo evento o basato su cron.', updated_at = now(), updated_by = 'migration-trigger-it', version = version + 1 WHERE key = 'job.entities.job_trigger.hints.next_run' AND language = 'it-IT' AND deleted_at IS NULL;
UPDATE job.translations SET value = 'Come costruire il payload della richiesta per la destinazione — per ogni campo di destinazione scegli un valore costante, un percorso nel payload dell''evento o un valore di contesto dell''attivatore (attore, id attivatore, ora di esecuzione). Lascia vuoto per inoltrare il payload dell''evento invariato.', updated_at = now(), updated_by = 'migration-trigger-it', version = version + 1 WHERE key = 'job.entities.job_trigger.hints.payload_map' AND language = 'it-IT' AND deleted_at IS NULL;
UPDATE job.translations SET value = '`originator` esegue l''azione come l''utente che ha innescato l''evento, con i suoi permessi — richiede una sorgente evento; `author` come l''autore dell''attivatore, identità risolta al momento dell''esecuzione; `system` con i privilegi del modulo.', updated_at = now(), updated_by = 'migration-trigger-it', version = version + 1 WHERE key = 'job.entities.job_trigger.hints.run_as' AND language = 'it-IT' AND deleted_at IS NULL;
UPDATE job.translations SET value = 'Quando l''attivatore scatta — `@every <n><unit>` per intervalli, `@at <timestamp>` per esecuzione singola, o un''espressione cron a 5 campi. Il pulsante assistente ne costruisce una per te.', updated_at = now(), updated_by = 'migration-trigger-it', version = version + 1 WHERE key = 'job.entities.job_trigger.hints.schedule_spec' AND language = 'it-IT' AND deleted_at IS NULL;
UPDATE job.translations SET value = 'L''identificativo stabile del modulo per questo job — l''ancora su cui le nuove release si riconciliano. Vuoto sugli attivatori creati da te.', updated_at = now(), updated_by = 'migration-trigger-it', version = version + 1 WHERE key = 'job.entities.job_trigger.hints.system_key' AND language = 'it-IT' AND deleted_at IS NULL;
UPDATE job.translations SET value = 'Cosa fa l''attivatore quando scatta: l''operazione da eseguire (per esempio inviare un''email). Le destinazioni disponibili dipendono dai servizi attivi.', updated_at = now(), updated_by = 'migration-trigger-it', version = version + 1 WHERE key = 'job.entities.job_trigger.hints.target_subject' AND language = 'it-IT' AND deleted_at IS NULL;
UPDATE job.translations SET value = 'Emesso quando l''insieme degli attivatori job cambia — `jobs` dominio, `ctl` canale di controllo, `triggers` risorsa, `changed` verbo. Il motore degli attivatori ri-arma le pianificazioni.', updated_at = now(), updated_by = 'migration-trigger-it', version = version + 1 WHERE key = 'job.events.triggers_changed.desc' AND language = 'it-IT' AND deleted_at IS NULL;
UPDATE job.translations SET value = 'Disabilitare ogni schedule armata? Gli attivatori verranno spenti e i job infra soppressi finché non vengono riabilitati manualmente.', updated_at = now(), updated_by = 'migration-trigger-it', version = version + 1 WHERE key = 'job.jobs.actions.disarm_all_confirm' AND language = 'it-IT' AND deleted_at IS NULL;
UPDATE job.translations SET value = 'Riprendere ogni schedule in pausa? Gli attivatori si ri-derivano e gli owner infra ricevono una richiesta di ri-arm.', updated_at = now(), updated_by = 'migration-trigger-it', version = version + 1 WHERE key = 'job.jobs.actions.resume_all_confirm' AND language = 'it-IT' AND deleted_at IS NULL;
